import {describe,expect,it} from 'vitest';
import {parseNativeUserSourceDraftV3,parseNativeUserSourceCheckV3,parseNativeUserSourceSaveRequestV3,parseNativeUserSourceSaveResultV3,parseNativeUserSourcesV3,parseNativeBuiltinPublicCatalogV1} from './native-user-source-v3.js';
import {parseNativeUserSourceDraftV2,parseNativeUserSourceSaveResultV2} from './native-user-sources.js';
const op='11111111-1111-4111-8111-111111111111',stamp='2026-10-11T01:00:00.000Z';
const draft={schemaVersion:3,internalId:null,expectedLocalRevision:null,name:'我的来源',apiKey:'synthetic-key',sourcePresetId:'kimi',advanced:null,probeSelection:null};
const model={logicalModelId:'kimi.kimi-k3',providerId:'kimi',exactModelId:'kimi-k3',displayName:'Kimi',protocol:'openai_chat_completions',contextWindow:262144,maxOutputTokens:32768,capabilityFlags:['tool_use'],evidenceSha256:'a'.repeat(64),membershipRevision:'manual-r1',capabilityRevision:'manual-r1',adapterRevision:'adapter-r1',priceAuthorityRevision:null,availability:'available'};
const inventory={schemaVersion:2,inventoryRevision:'b'.repeat(64),fetchedAt:stamp,endpoint:'https://api.moonshot.cn/v1/models',responseSha256:['c'.repeat(64)],models:[{exactModelId:'kimi-k3',ownedBy:null,lifecycle:null,shutdownDate:null}]};
const discovery={schemaVersion:3,route:'domestic_private',state:'discovered',sourceRevision:null,inventory,ping:{success:true,latencyMs:2,url:'https://api.moonshot.cn/v1',errorCode:null},probe:null,probeSelection:null,admittedModels:[model],verificationId:null,verifiedAt:null,expiresAt:null,errorCode:null};
const saved={schemaVersion:3,operationId:op,state:'saved',route:'domestic_private',localRef:'m-owned',localRevision:'d'.repeat(64),sourceRevision:'e'.repeat(64),inventoryRevision:inventory.inventoryRevision,pendingPhase:null};
describe('independent neutral source schema 3',()=>{
 it('accepts eight neutral presets while preserving V2 version rejection',()=>{for(const sourcePresetId of ['deepseek','kimi','hunyuan','zhipu','minimax','mimo','openai','anthropic'])expect(parseNativeUserSourceDraftV3({...draft,sourcePresetId}).sourcePresetId).toBe(sourcePresetId);expect(()=>parseNativeUserSourceDraftV2(draft)).toThrow();expect(()=>parseNativeUserSourceSaveResultV2(saved)).toThrow()});
 it('requires closed owned CAS and explicit nullable detection selection',()=>{for(const key of Object.keys(draft)){const v:any={...draft};delete v[key];expect(()=>parseNativeUserSourceDraftV3(v)).toThrow()};expect(()=>parseNativeUserSourceDraftV3({...draft,toolId:'codex'})).toThrow();expect(()=>parseNativeUserSourceDraftV3({...draft,internalId:'m-owned'})).toThrow();expect(()=>parseNativeUserSourceDraftV3({...draft,probeSelection:{exactModelId:'kimi-k3',protocol:'openai_chat_completions',available:true}})).toThrow()});
 it('discovery has no proof and cannot authorize save',()=>{expect(parseNativeUserSourceCheckV3(discovery)).toEqual(discovery);expect(()=>parseNativeUserSourceCheckV3({...discovery,verificationId:op})).toThrow();expect(()=>parseNativeUserSourceSaveRequestV3({schemaVersion:3,operationId:op,draft,verificationId:op})).toThrow()});
 it('source proof requires exact explicit selection and admission, without paid probe or readiness claim',()=>{const selection={exactModelId:model.exactModelId,protocol:model.protocol},check={...discovery,state:'source_checked',probeSelection:selection,sourceRevision:saved.sourceRevision,verificationId:op,verifiedAt:stamp,expiresAt:'2026-10-11T01:10:00.000Z'};expect(parseNativeUserSourceCheckV3(check)).toEqual(check);for(const changed of [{admittedModels:[]},{probeSelection:{...selection,exactModelId:'unreviewed'}},{probe:{protocol:model.protocol,success:true,returnedModel:model.exactModelId,response:'OK'}}])expect(()=>parseNativeUserSourceCheckV3({...check,...changed})).toThrow();expect(parseNativeUserSourceSaveRequestV3({schemaVersion:3,operationId:op,draft:{...draft,probeSelection:selection},verificationId:op}).operationId).toBe(op)});
 it('saved means owned source durability and includes original operation identity only',()=>{expect(parseNativeUserSourceSaveResultV3(saved)).toEqual(saved);expect(()=>parseNativeUserSourceSaveResultV3({...saved,registration:{}})).toThrow();expect(()=>parseNativeUserSourceSaveResultV3({...saved,pendingPhase:'host_apply'})).toThrow();expect(()=>parseNativeUserSourceSaveResultV3({...saved,state:'ready'})).toThrow();expect(parseNativeUserSourceSaveResultV3({...saved,state:'pending',pendingPhase:'local_publish'}).state).toBe('pending')});
 it('safe views contain configuration and explicit tested selection, never Key',()=>{const view={schemaVersion:3,localRef:saved.localRef,localRevision:saved.localRevision,sourceRevision:saved.sourceRevision,name:draft.name,route:saved.route,inventory,probeSelection:{exactModelId:model.exactModelId,protocol:model.protocol},state:'saved',operationId:op,configuration:{providerId:'kimi',sourcePresetId:'kimi',baseUrl:'https://api.moonshot.cn/v1',anthropicUrl:null}};expect(parseNativeUserSourcesV3([view])).toEqual([view]);expect(()=>parseNativeUserSourcesV3([{...view,apiKey:'synthetic'}])).toThrow();expect(()=>parseNativeUserSourcesV3([{...view,probeSelection:null}])).toThrow();expect(()=>parseNativeUserSourcesV3([view,view])).toThrow()});
 it('manual catalog is leased and keyless; empty admission stays empty',()=>{const catalog={schemaVersion:1,catalogRevision:'manual-r1',checkedAt:stamp,expiresAt:'2026-10-12T01:00:00.000Z',models:[model],transports:[{providerId:'kimi',protocol:model.protocol,baseUrl:'https://api.moonshot.cn/v1',adapterRevision:model.adapterRevision,evidenceSha256:model.evidenceSha256}]};expect(parseNativeBuiltinPublicCatalogV1(catalog)).toEqual(catalog);expect(parseNativeBuiltinPublicCatalogV1({...catalog,models:[],transports:[]}).models).toEqual([]);for(const change of [{apiKey:'synthetic'},{expiresAt:stamp},{models:[model,model]},{transports:[catalog.transports[0],catalog.transports[0]]}])expect(()=>parseNativeBuiltinPublicCatalogV1({...catalog,...change})).toThrow()});
});
